import type { Vec2 } from '@foomerang/game-core';
import type { FuArena, Rect } from './arena';

/**
 * MARKET PLAZA (`market_plaza`) — the first map reconstructed from the master gameplay video (`foomerang-fu gameplay.mp4`, shots
 * S4/S5, frames 201–372), as DATA owned by the rules. Presentation draws it; it never decides what blocks anything.
 *
 * Generated by art/reconstruction/runtime/gen_plaza_arena.py from the measured reconstruction (camera solved per frame, layout
 * from rectified plans, stall roofs unprojected from two cameras). World mapping shared with the renderer: 1 Blender unit = 20
 * world units, X = (x + 50) * 20, Y = (100 - y) * 20. The playable area is the plaza between the left fence (x -50 BU), x 37.5 BU (the take-A frame edge at the bottom) and the far wall
 * as seen by the take-A camera (REFERENCE-CONSTRAINED); the boundary itself is INFERRED (the video shows no edge collision).
 *
 * Solid: market stalls (45-degree stalls as two crossed rectangles), the fountain (three overlapping rectangles), the two far
 * stalls and the crates. Pots, poles, bushes and bunting are decoration. No gates, platforms or hazards: no new mechanic.
 */

export const MARKET_PLAZA_WIDTH = 1750;
export const MARKET_PLAZA_HEIGHT = 1300;

export interface MarketPlazaWall extends Rect {
  readonly id: string;
  readonly kind: 'STALL' | 'FOUNTAIN' | 'CRATE';
}

